98	
99	export interface Importacao {
100	  id: string;
101	  data: DataISO;
102	  contaId: string;
103	  transacaoIds: string[];
104	}
105	
106	/** Pagamento de fatura: movimenta dinheiro entre contas e não é receita nem despesa. */
107	export interface PagamentoFatura {
108	  id: string;
109	  contaCartaoId: string;
110	  /** Mês de fechamento da fatura (AAAA-MM). */
111	  mesFatura: Mes;
