130	export type Resultado<T> = { ok: true; valor: T } | { ok: false; erro: string; campo?: string };
131	
132	export const ok = <T>(valor: T): Resultado<T> => ({ ok: true, valor });
133	export const falha = (erro: string, campo?: string): Resultado<never> => ({ ok: false, erro, campo });
