1	import { categoriasPadrao } from '../data/categoriasPadrao';
2	import { falha, ok, type AppState, type Resultado } from '../domain/types';
3	
4	/** Toda chave escrita pelo app começa com este prefixo. */
5	export const PREFIXO = 'financas:';
6	export const CHAVE_ESTADO = `${PREFIXO}estado`;
7	export const SCHEMA_ATUAL = 2;
8	
9	export function estadoInicial(): AppState {
10	  return {
11	    schemaVersion: SCHEMA_ATUAL,
12	    contas: [],
13	    categorias: categoriasPadrao(),
14	    transacoes: [],
15	    orcamentos: [],
16	    metas: [],
17	    recorrencias: [],
18	    mapeamentosCsv: {},
19	    importacoes: [],
20	    pagamentosFatura: [],
21	  };
22	}
23	
24	export type Carga =
25	  | { tipo: 'ok'; estado: AppState }
26	  | { tipo: 'corrompido'; bruto: string }
27	  | { tipo: 'versao-futura'; bruto: string; versao: number };
28	
29	type Dados = Record<string, unknown>;
30	
31	/** Migrações indexadas pela versão de origem: `migracoes[n]` leva de n para n+1. */
32	const migracoes: Record<number, (dados: Dados) => Dados> = {
33	  0: (dados) => ({
34	    ...dados,
35	    schemaVersion: 1,
36	    contas: dados.contas ?? [],
37	    categorias: dados.categorias ?? categoriasPadrao(),
38	    transacoes: dados.transacoes ?? [],
39	    orcamentos: dados.orcamentos ?? [],
40	    metas: dados.metas ?? [],
41	    recorrencias: dados.recorrencias ?? [],
42	    mapeamentosCsv: dados.mapeamentosCsv ?? {},
43	    importacoes: dados.importacoes ?? [],
44	  }),
45	  // v2: pagamentos de fatura de cartão.
46	  1: (dados) => ({ ...dados, schemaVersion: 2, pagamentosFatura: dados.pagamentosFatura ?? [] }),
47	};
48	
49	const CHAVES_LISTA = ['contas', 'categorias', 'transacoes', 'orcamentos', 'metas', 'recorrencias', 'importacoes', 'pagamentosFatura'] as const;
50	
51	function ehObjeto(x: unknown): x is Dados {
52	  return typeof x === 'object' && x !== null && !Array.isArray(x);
53	}
54	
55	function estruturaValida(dados: Dados): boolean {
56	  return (
57	    CHAVES_LISTA.every((k) => Array.isArray(dados[k])) &&
58	    ehObjeto(dados.mapeamentosCsv) &&
59	    dados.schemaVersion === SCHEMA_ATUAL
60	  );
61	}
62	
63	/** Migra um objeto qualquer até a versão atual. Versões futuras são recusadas. */
64	export function migrar(bruto: unknown): { tipo: 'ok'; estado: AppState } | { tipo: 'corrompido' } | { tipo: 'versao-futura'; versao: number } {
65	  if (!ehObjeto(bruto)) return { tipo: 'corrompido' };
66	  let dados: Dados = bruto;
67	  const versaoLida = dados.schemaVersion === undefined ? 0 : dados.schemaVersion;
68	  if (typeof versaoLida !== 'number' || !Number.isInteger(versaoLida) || versaoLida < 0) {
69	    return { tipo: 'corrompido' };
70	  }
71	  if (versaoLida > SCHEMA_ATUAL) return { tipo: 'versao-futura', versao: versaoLida };
72	  if (versaoLida === 0 && !CHAVES_LISTA.some((k) => k in dados)) return { tipo: 'corrompido' };
73	  for (let v = versaoLida; v < SCHEMA_ATUAL; v++) {
74	    const migracao = migracoes[v];
75	    if (!migracao) return { tipo: 'corrompido' };
76	    dados = migracao(dados);
77	  }
78	  // Chaves aditivas (novos módulos) ausentes em dados antigos recebem o valor inicial, sem migração.
79	  const padrao = estadoInicial() as unknown as Dados;
80	  for (const chave of Object.keys(padrao)) if (dados[chave] === undefined) dados = { ...dados, [chave]: padrao[chave] };
81	  if (!estruturaValida(dados)) return { tipo: 'corrompido' };
82	  return { tipo: 'ok', estado: dados as unknown as AppState };
83	}
84	
85	export function carregar(storage: Storage): Carga {
86	  let bruto: string | null;
87	  try {
88	    bruto = storage.getItem(CHAVE_ESTADO);
89	  } catch {
90	    return { tipo: 'ok', estado: estadoInicial() };
91	  }
92	  if (bruto === null) return { tipo: 'ok', estado: estadoInicial() };
93	  let parsed: unknown;
94	  try {
95	    parsed = JSON.parse(bruto);
96	  } catch {
97	    return { tipo: 'corrompido', bruto };
98	  }
99	  const r = migrar(parsed);
100	  if (r.tipo === 'ok') return r;
101	  if (r.tipo === 'versao-futura') return { tipo: 'versao-futura', bruto, versao: r.versao };
102	  return { tipo: 'corrompido', bruto };
103	}
104	
105	/** Lança se o navegador recusar a gravação (cota excedida, armazenamento bloqueado). */
106	export function salvar(estado: AppState, storage: Storage): void {
107	  storage.setItem(CHAVE_ESTADO, JSON.stringify(estado));
108	}
109	
110	export function apagarTudo(storage: Storage): void {
111	  const chaves: string[] = [];
112	  for (let i = 0; i < storage.length; i++) {
113	    const chave = storage.key(i);
114	    if (chave?.startsWith(PREFIXO)) chaves.push(chave);
115	  }
116	  chaves.forEach((c) => storage.removeItem(c));
117	}
118	
119	export function exportarJson(estado: AppState): string {
120	  return JSON.stringify(estado, null, 2);
121	}
122	
123	/** Lê um arquivo de exportação, migrando se necessário. */
124	export function importarJson(texto: string): Resultado<AppState> {
125	  let parsed: unknown;
126	  try {
127	    parsed = JSON.parse(texto);
128	  } catch {
129	    return falha('O arquivo não é um JSON válido.');
130	  }
131	  const r = migrar(parsed);
132	  if (r.tipo === 'ok') return ok(r.estado);
133	  if (r.tipo === 'versao-futura') {
134	    return falha(`O arquivo foi gerado por uma versão mais nova do app (esquema ${r.versao}).`);
135	  }
136	  return falha('O arquivo não parece ser uma exportação deste app.');
137	}
