29	export function CartoesPage() {
30	  const store = useStore();
31	  const estado = useEstado();
32	  const [params, setParams] = useSearchParams();
33	  const [erro, setErro] = useState<string | null>(null);
34	  const hoje = hojeISO();
35	
36	  const cartoes = cartoesAtivos(estado.contas);
37	  const escolhido = cartoes.find((c) => c.id === params.get('cartao')) ?? cartoes[0];
38	  const mesParam = params.get('mes') ?? '';
39	  const mes = mesValido(mesParam) ? mesParam : escolhido?.cartao ? mesFaturaAberta(escolhido.cartao, hoje) : hoje.slice(0, 7);
40	
41	  const resumo = useMemo(() => (escolhido ? resumoFatura(estado, escolhido, mes, hoje) : null), [estado, escolhido, mes, hoje]);
42	  const limite = useMemo(() => (escolhido ? limiteCartao(estado, escolhido) : null), [estado, escolhido]);
43	  const categorias = new Map(estado.categorias.map((c) => [c.id, c.nome]));
44	  const pagamentos = estado.pagamentosFatura.filter((p) => escolhido && p.contaCartaoId === escolhido.id && p.mesFatura === mes);
45	  const contasOrigem = estado.contas.filter((c) => !c.arquivada && c.tipo !== 'cartao');
46	  const nomeConta = new Map(estado.contas.map((c) => [c.id, c.nome]));
47	
48	  const navegar = (parcial: Record<string, string>) => setParams({ ...(escolhido ? { cartao: escolhido.id } : {}), mes, ...parcial }, { replace: true });
49	
50	  if (!escolhido) {
51	    return (
52	      <div>
53	        <TituloPagina>Cartões</TituloPagina>
54	        <EstadoVazio titulo="Nenhum cartão de crédito" acao={<Link to="/contas" className="font-medium text-emerald-800 underline">Criar um cartão em Contas</Link>}>
55	          Cadastre uma conta do tipo cartão de crédito para acompanhar faturas, limite e parcelas.
56	        </EstadoVazio>
57	      </div>
58	    );
59	  }
60	
61	  return (
62	    <div>
63	      <TituloPagina>Cartões</TituloPagina>
64	      <div className="space-y-4">
65	        {erro ? <Alerta>{erro}</Alerta> : null}
66	        <Cartao>
67	          <div className="grid gap-3 sm:grid-cols-2">
68	            <CampoSelect label="Cartão" value={escolhido.id} onChange={(e) => setParams({ cartao: e.target.value })}>
69	              {cartoes.map((c) => (
70	                <option key={c.id} value={c.id}>
71	                  {c.nome}
72	                </option>
73	              ))}
74	            </CampoSelect>
75	          </div>
76	        </Cartao>
77	
78	        {!escolhido.cartao || !resumo || !limite ? (
79	          <EstadoVazio titulo="Cartão sem ciclo configurado" acao={<Link to="/contas" className="font-medium text-emerald-800 underline">Configurar em Contas</Link>}>
80	            Edite a conta "{escolhido.nome}" e informe o dia de fechamento, o dia de vencimento e o limite.
81	          </EstadoVazio>
82	        ) : (
83	          <>
84	            <Cartao titulo="Limite">
85	              <LimiteCartaoBarra limite={limite} total={escolhido.cartao.limite} />
86	            </Cartao>
87	
88	            <Cartao>
89	              <div className="flex flex-wrap items-end gap-3">
90	                <Botao variante="secundario" onClick={() => navegar({ mes: somarMeses(mes, -1) })}>
91	                  Fatura anterior
92	                </Botao>
93	                <div className="w-44">
94	                  <CampoTexto label="Mês da fatura" type="month" value={mes} onChange={(e) => mesValido(e.target.value) && navegar({ mes: e.target.value })} />
95	                </div>
96	                <Botao variante="secundario" onClick={() => navegar({ mes: somarMeses(mes, 1) })}>
97	                  Próxima fatura
98	                </Botao>
99	              </div>
100	            </Cartao>
101	
102	            <Cartao
103	              titulo={`Fatura de ${nomeMes(mes)}`}
104	              acoes={
105	                <span className={`rounded-full px-2.5 py-0.5 text-xs font-semibold ${COR_SITUACAO[resumo.situacao]}`} data-testid="situacao">
106	                  {ROTULO_SITUACAO[resumo.situacao]}
107	                </span>
108	              }
109	            >
110	              <p className="mb-3 text-sm text-slate-600" data-testid="ciclo">
111	                Ciclo de {formatarData(cicloFatura(escolhido.cartao, mes).inicio)} a {formatarData(cicloFatura(escolhido.cartao, mes).fim)} · vence em{' '}
112	                <span data-testid="vencimento">{formatarData(resumo.vencimento)}</span>
113	              </p>
114	              <dl className="mb-3 grid gap-2 text-sm sm:grid-cols-3">
115	                <div>
116	                  <dt className="text-slate-600">Total da fatura</dt>
117	                  <dd className="text-lg font-bold" data-testid="fatura-total">{formatarMoeda(resumo.total)}</dd>
118	                </div>
119	                <div>
120	                  <dt className="text-slate-600">Pago</dt>
121	                  <dd data-testid="fatura-pago">{formatarMoeda(resumo.pago)}</dd>
122	                </div>
123	                <div>
124	                  <dt className="text-slate-600">Restante</dt>
125	                  <dd data-testid="fatura-restante">{formatarMoeda(resumo.restante)}</dd>
126	                </div>
127	              </dl>
128	              {resumo.transacoes.length === 0 ? (
129	                <p className="text-sm text-slate-600">Nenhuma compra neste ciclo.</p>
130	              ) : (
131	                <ul className="divide-y divide-slate-200" aria-label="Compras da fatura">
132	                  {resumo.transacoes.map((t) => (
133	                    <li key={t.id} className="flex flex-wrap items-center justify-between gap-2 py-2 text-sm">
134	                      <span className="min-w-0">
135	                        <span className="block truncate font-medium text-slate-900">{t.descricao || 'Sem descrição'}</span>
136	                        <span className="text-xs text-slate-600">
137	                          {formatarData(t.data)} · {categorias.get(t.categoriaId) ?? 'Sem categoria'}
138	                        </span>
139	                      </span>
140	                      <Valor centavos={t.tipo === 'despesa' ? -t.valor : t.valor} texto={formatarMoeda(t.tipo === 'despesa' ? -t.valor : t.valor)} />
141	                    </li>
142	                  ))}
143	                </ul>
144	              )}
145	            </Cartao>
146	
147	            <Cartao titulo="Pagamentos desta fatura">
148	              {pagamentos.length > 0 ? (
149	                <ul className="mb-4 divide-y divide-slate-200" aria-label="Pagamentos registrados">
150	                  {pagamentos.map((p) => (
151	                    <li key={p.id} className="flex flex-wrap items-center justify-between gap-2 py-2 text-sm">
152	                      <span>
153	                        {formatarData(p.data)} · de {nomeConta.get(p.contaOrigemId) ?? 'conta removida'} · {formatarMoeda(p.valor)}
154	                      </span>
155	                      <Botao
156	                        variante="secundario"
157	                        aria-label={`Excluir pagamento de ${formatarData(p.data)}`}
158	                        onClick={() => setErro(store.aplicar((s) => excluirPagamento(s, p.id)).ok ? null : 'Não foi possível excluir o pagamento.')}
159	                      >
160	                        Excluir
161	                      </Botao>
162	                    </li>
163	                  ))}
164	                </ul>
165	              ) : null}
166	              {resumo.restante > 0 ? (
167	                <PagamentoFaturaForm
168	                  key={`${escolhido.id}-${mes}-${resumo.restante}`}
169	                  contaCartaoId={escolhido.id}
170	                  mesFatura={mes}
171	                  restante={resumo.restante}
172	                  contasOrigem={contasOrigem}
173	                  onSalvar={(dados) => store.aplicar((s) => registrarPagamento(s, dados, hoje))}
174	                />
175	              ) : (
176	                <p className="text-sm text-slate-600">Não há valor a pagar nesta fatura.</p>
177	              )}
178	            </Cartao>
179	
180	            <Cartao titulo="Compra parcelada">
181	              <CompraParceladaForm contaId={escolhido.id} categorias={estado.categorias} onSalvar={(dados) => store.aplicar((s) => criarCompraParcelada(s, dados))} />
182	            </Cartao>
183	          </>
184	        )}
185	      </div>
186	    </div>
187	  );
188	}
