29	function dataNoMes(mes: Mes, dia: number): string {
30	  const [ano, m] = mes.split('-').map(Number);
31	  const d = Math.min(dia, diasNoMes(ano, m));
32	  return `${mes}-${String(d).padStart(2, '0')}`;
33	}
