35	/**
36	 * Gera um conjunto de dados de exemplo relativo à data informada: quatro meses
37	 * completos de histórico mais o mês corrente até o dia de hoje.
38	 */
39	export function gerarExemplo(hoje: string): AppState {
40	  if (!dataValida(hoje)) throw new Error(`Data inválida: ${hoje}`);
41	  const mesAtual = mesDe(hoje);
42	  const criadaEm = 1;
43	
44	  const contas: Conta[] = [
45	    { id: ID_CORRENTE, nome: 'Conta corrente', tipo: 'corrente', saldoInicial: 250000, arquivada: false, criadaEm },
46	    { id: ID_POUPANCA, nome: 'Poupança', tipo: 'poupanca', saldoInicial: 1200000, arquivada: false, criadaEm: criadaEm + 1 },
47	    { id: ID_CARTAO, nome: 'Cartão de crédito', tipo: 'cartao', saldoInicial: 0, arquivada: false, criadaEm: criadaEm + 2, cartao: { diaFechamento: 20, diaVencimento: 27, limite: 500000 } },
48	    { id: ID_CARTEIRA, nome: 'Carteira', tipo: 'dinheiro', saldoInicial: 15000, arquivada: false, criadaEm: criadaEm + 3 },
49	  ];
50	
51	  const transacoes: Transacao[] = [];
52	  let sequencia = 0;
53	  const adicionar = (t: Omit<Transacao, 'id' | 'criadaEm'>) => {
54	    sequencia += 1;
55	    transacoes.push({ ...t, id: `ex-t-${sequencia}`, criadaEm: sequencia });
56	  };
57	
58	  for (let delta = -4; delta <= 0; delta++) {
59	    const mes = somarMeses(mesAtual, delta);
60	    const variacao = (delta + 5) * 1300;
61	    const lancamentos: Modelo[] = [
62	      [5, 'Salário', 550000, 'cat-salario', ID_CORRENTE],
63	      [28, 'Rendimento da poupança', 6800 + variacao / 10, 'cat-rendimentos', ID_POUPANCA],
64	      ...despesasMensais.map((m): Modelo => [m[0], m[1], m[2] + (m[4] === ID_CARTAO ? variacao % 5000 : 0), m[3], m[4]]),
65	    ];
66	    for (const [dia, descricao, valor, categoriaId, contaId] of lancamentos) {
67	      const data = dataNoMes(mes, dia);
68	      if (data > hoje) continue;
69	      adicionar({
70	        contaId,
71	        categoriaId,
72	        tipo: categoriaId === 'cat-salario' || categoriaId === 'cat-rendimentos' ? 'receita' : 'despesa',
73	        valor: Math.round(valor),
74	        data,
75	        descricao,
76	      });
77	    }
78	  }
79	
80	  const orcamentos: Orcamento[] = (
81	    [
82	      ['cat-moradia', 190000],
83	      ['cat-alimentacao', 140000],
84	      ['cat-transporte', 35000],
85	      ['cat-saude', 20000],
86	      ['cat-lazer', 25000],
87	    ] as const
88	  ).map(([categoriaId, limite]) => ({ categoriaId, mes: mesAtual, limite }));
89	
90	  const aportes = (valores: number[], idMeta: string): Aporte[] =>
91	    valores.map((valor, i) => ({
92	      id: `${idMeta}-a${i}`,
93	      data: dataNoMes(somarMeses(mesAtual, i - valores.length), 15),
94	      valor,
95	    }));
96	
97	  const metas: Meta[] = [
98	    {
99	      id: 'ex-meta-reserva',
100	      nome: 'Reserva de emergência',
101	      valorAlvo: 3000000,
102	      aportes: aportes([200000, 200000, 150000, 200000], 'ex-meta-reserva'),
103	      status: 'ativa',
104	      criadaEm: 1,
105	    },
106	    {
107	      id: 'ex-meta-viagem',
108	      nome: 'Viagem de férias',
109	      valorAlvo: 800000,
110	      prazo: dataNoMes(somarMeses(mesAtual, 8), 10),
111	      aportes: aportes([60000, 50000, 70000], 'ex-meta-viagem'),
112	      status: 'ativa',
113	      criadaEm: 2,
114	    },
115	  ];
116	
117	  const recorrencias: Recorrencia[] = [
118	    { id: 'ex-rec-salario', descricao: 'Salário', tipo: 'receita', valor: 550000, categoriaId: 'cat-salario', ativa: true },
119	    { id: 'ex-rec-aluguel', descricao: 'Aluguel', tipo: 'despesa', valor: 150000, categoriaId: 'cat-moradia', ativa: true },
120	  ];
121	
122	  return {
123	    schemaVersion: SCHEMA_ATUAL,
124	    contas,
125	    categorias: categoriasPadrao(),
126	    transacoes,
127	    orcamentos,
128	    metas,
129	    recorrencias,
130	    mapeamentosCsv: {},
131	    importacoes: [],
132	    pagamentosFatura: [],
133	  };
134	}
