16	type Erros = Partial<Record<'valor' | 'data' | 'contaOrigemId' | 'geral', string>>;
17	
18	export function PagamentoFaturaForm({ contaCartaoId, mesFatura, restante, contasOrigem, onSalvar }: Props) {
19	  const [valor, setValor] = useState(restante > 0 ? valorParaCampo(restante) : '');
20	  const [data, setData] = useState(hojeISO());
21	  const [origem, setOrigem] = useState(contasOrigem[0]?.id ?? '');
22	  const [erros, setErros] = useState<Erros>({});
23	
24	  if (contasOrigem.length === 0) {
25	    return <Alerta tipo="aviso">Para pagar a fatura é preciso ter uma conta ativa que não seja cartão.</Alerta>;
26	  }
27	
28	  const enviar = (e: FormEvent) => {
29	    e.preventDefault();
30	    const centavos = parseValor(valor);
31	    if (centavos === null) return setErros({ valor: 'Informe um valor válido, como 350,00.' });
32	    const r = onSalvar({ contaCartaoId, mesFatura, valor: centavos, data, contaOrigemId: origem });
33	    if (!r.ok) return setErros(r.campo ? { [r.campo]: r.erro } : { geral: r.erro });
34	    setErros({});
35	  };
36	
37	  return (
38	    <form onSubmit={enviar} noValidate aria-label="Pagar fatura" className="grid gap-3 sm:grid-cols-3">
39	      <CampoTexto label="Valor do pagamento" value={valor} onChange={(e) => setValor(e.target.value)} erro={erros.valor} inputMode="decimal" placeholder="0,00" />
40	      <CampoTexto label="Data do pagamento" type="date" value={data} onChange={(e) => setData(e.target.value)} erro={erros.data} />
