2	
3	export function dataParaISO(d: Date): DataISO {
4	  const mm = String(d.getMonth() + 1).padStart(2, '0');
5	  const dd = String(d.getDate()).padStart(2, '0');
6	  return `${d.getFullYear()}-${mm}-${dd}`;
7	}
8	
9	export function hojeISO(): DataISO {
10	  return dataParaISO(new Date());
11	}
12	
13	export function diasNoMes(ano: number, mes: number): number {
14	  return new Date(Date.UTC(ano, mes, 0)).getUTCDate();
15	}
16	
17	/** Valida `AAAA-MM-DD` incluindo dias inexistentes como 31/02. */
18	export function dataValida(iso: string): boolean {
19	  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
20	  if (!m) return false;
21	  const [ano, mes, dia] = [Number(m[1]), Number(m[2]), Number(m[3])];
22	  if (ano < 1900 || ano > 2200 || mes < 1 || mes > 12) return false;
23	  return dia >= 1 && dia <= diasNoMes(ano, mes);
24	}
25	
26	export function mesDe(data: DataISO): Mes {
27	  return data.slice(0, 7);
28	}
29	
30	export function somarMeses(mes: Mes, n: number): Mes {
31	  const [ano, m] = mes.split('-').map(Number);
32	  const total = ano * 12 + (m - 1) + n;
33	  return `${Math.floor(total / 12)}-${String((total % 12) + 1).padStart(2, '0')}`;
34	}
35	
36	/** Diferença em meses (b - a). */
37	export function diferencaMeses(a: Mes, b: Mes): number {
38	  const [aa, am] = a.split('-').map(Number);
39	  const [ba, bm] = b.split('-').map(Number);
40	  return (ba - aa) * 12 + (bm - am);
41	}
42	
43	export function formatarData(iso: DataISO): string {
44	  const [ano, mes, dia] = iso.split('-');
45	  return `${dia}/${mes}/${ano}`;
46	}
47	
48	export function mesValido(mes: string): boolean {
49	  return /^\d{4}-(0[1-9]|1[0-2])$/.test(mes);
50	}
51	
52	const nomesMeses = [
53	  'janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho',
54	  'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro',
55	];
56	
57	export function nomeMes(mes: Mes): string {
58	  const [ano, m] = mes.split('-').map(Number);
59	  return `${nomesMeses[m - 1]} de ${ano}`;
60	}
61	
62	export function nomeMesCurto(mes: Mes): string {
63	  const [ano, m] = mes.split('-').map(Number);
64	  return `${nomesMeses[m - 1].slice(0, 3)}/${String(ano).slice(2)}`;
65	}
66	
67	export function primeiroDia(mes: Mes): DataISO {
68	  return `${mes}-01`;
69	}
70	
71	export function ultimoDia(mes: Mes): DataISO {
72	  const [ano, m] = mes.split('-').map(Number);
73	  return `${mes}-${String(diasNoMes(ano, m)).padStart(2, '0')}`;
74	}
