1	import { createContext, useContext, useSyncExternalStore, type ReactNode } from 'react';
2	import { apagarTudo, carregar, estadoInicial, salvar } from '../storage/storage';
3	import { falha, ok, type AppState, type Resultado } from '../domain/types';
4	
5	export type Problema =
6	  | { tipo: 'corrompido'; bruto: string }
7	  | { tipo: 'versao-futura'; bruto: string; versao: number };
8	
9	export interface Snapshot {
10	  estado: AppState;
11	  problema: Problema | null;
12	}
13	
14	const MSG_GRAVACAO =
15	  'Não foi possível gravar no navegador (armazenamento cheio ou bloqueado). Nada foi alterado.';
16	
17	/**
18	 * Guarda o estado em memória e o persiste no storage a cada alteração.
19	 * Se a gravação falhar, o estado em memória não muda.
20	 */
21	export class Store {
22	  private snap: Snapshot;
23	  private ouvintes = new Set<() => void>();
24	
25	  constructor(private readonly storage: Storage) {
26	    const carga = carregar(storage);
27	    this.snap =
28	      carga.tipo === 'ok'
29	        ? { estado: carga.estado, problema: null }
30	        : { estado: estadoInicial(), problema: carga };
31	  }
32	
33	  getSnapshot = (): Snapshot => this.snap;
34	
35	  subscribe = (ouvinte: () => void): (() => void) => {
36	    this.ouvintes.add(ouvinte);
37	    return () => {
38	      this.ouvintes.delete(ouvinte);
39	    };
40	  };
41	
42	  /** Aplica uma operação pura sobre o estado; só persiste se ela der certo. */
43	  aplicar = (operacao: (estado: AppState) => Resultado<AppState>): Resultado<void> => {
44	    if (this.snap.problema) return falha('Os dados salvos não foram carregados; resolva isso antes de continuar.');
45	    const r = operacao(this.snap.estado);
46	    if (!r.ok) return r;
47	    return this.gravar(r.valor);
48	  };
49	
50	  /** Troca todo o estado (importação, exemplo, recomeço), inclusive resolvendo um problema de carga. */
51	  substituir = (estado: AppState): Resultado<void> => this.gravar(estado);
52	
53	  iniciarVazio = (): Resultado<void> => this.gravar(estadoInicial());
54	
55	  /** Remove todas as chaves do app e volta ao primeiro uso. */
56	  apagarTudo = (): void => {
57	    apagarTudo(this.storage);
58	    this.snap = { estado: estadoInicial(), problema: null };
59	    this.emitir();
60	  };
61	
62	  private gravar(estado: AppState): Resultado<void> {
63	    try {
64	      salvar(estado, this.storage);
65	    } catch {
66	      return falha(MSG_GRAVACAO);
67	    }
68	    this.snap = { estado, problema: null };
69	    this.emitir();
70	    return ok(undefined);
71	  }
72	
73	  private emitir(): void {
74	    this.ouvintes.forEach((o) => o());
75	  }
76	}
77	
78	const StoreContext = createContext<Store | null>(null);
79	
80	export function StoreProvider({ store, children }: { store: Store; children: ReactNode }) {
81	  return <StoreContext.Provider value={store}>{children}</StoreContext.Provider>;
82	}
83	
84	export function useStore(): Store {
85	  const store = useContext(StoreContext);
86	  if (!store) throw new Error('useStore precisa estar dentro de StoreProvider');
87	  return store;
88	}
89	
90	export function useSnapshot(): Snapshot {
91	  const store = useStore();
92	  return useSyncExternalStore(store.subscribe, store.getSnapshot);
93	}
94	
95	export function useEstado(): AppState {
96	  return useSnapshot().estado;
97	}
