  });

  it('critério 14: a navegação tem o item Dívidas para /dividas', () => {
    expect(itensNavegacao).toContainEqual({ to: '/dividas', rotulo: 'Dívidas' });
    renderizarApp('/');
    expect(screen.getAllByRole('link', { name: 'Dívidas' })[0]).toHaveAttribute('href', '/dividas');
  });
});

